  {en:"Separate wheat grains and husk",pu:"ਕਣਕ ਦੇ ਦਾਣੇ ਅਤੇ ਭੂਸਾ ਵੱਖ ਕਰਨਾ",method:"Winnowing",methodPu:"ਫਟਕਣਾ",steps:"Moving air carries the lighter husk farther away, while heavier wheat grains fall nearer to the tray.",stepsPu:"ਹਵਾ ਦਾ ਵਹਾਅ ਹਲਕੇ ਭੂਸੇ ਨੂੰ ਦੂਰ ਲੈ ਜਾਂਦਾ ਹੈ, ਜਦਕਿ ਭਾਰੀ ਕਣਕ ਦੇ ਦਾਣੇ ਟਰੇ ਦੇ ਨੇੜੇ ਡਿੱਗਦੇ ਹਨ।",art:"<path d='M65 80Q130 55 195 80L180 112Q130 130 80 112Z' fill='#e8c58f' stroke='#9b7548' stroke-width='4'/><g fill='#d6a33d' stroke='#a87925' stroke-width='1.5'><ellipse cx='105' cy='91' rx='5' ry='10' transform='rotate(-35 105 91)'/><ellipse cx='130' cy='98' rx='5' ry='10' transform='rotate(25 130 98)'/><ellipse cx='155' cy='88' rx='5' ry='10' transform='rotate(-20 155 88)'/></g><g stroke='#77a9c6' stroke-width='4' fill='none' stroke-linecap='round'><path d='M25 55Q70 35 105 58M35 75Q72 58 105 76M30 95Q65 85 92 96'/><path d='M92 51l13 7 -13 5M92 69l13 7 -13 5M80 89l13 7 -13 5'/></g><g stroke='#c3a05b' stroke-width='3'><path d='M225 48l-8 15m20 -9l-9 16m-4 9l-9 15'/></g>"}
