  $("#seVisual").innerHTML='<svg viewBox="0 0 650 280" class="c9-se-svg" role="img" aria-label="Static electricity attraction demonstration"><rect width="650" height="280" rx="18" fill="#f7fbff"/><text x="325" y="25" text-anchor="middle" font-size="15" font-weight="950" fill="#173b55">'+data.title+'</text><path d="M55 218 H595" stroke="#cbd5e1" stroke-width="3"/>'+object+arrows+target+'<g fill="#2563eb" font-size="16" font-weight="950"><text x="110" y="205">−</text><text x="150" y="215">−</text><text x="190" y="205">−</text></g><text x="325" y="265" text-anchor="middle" font-size="12" font-weight="900" fill="#0f766e">'+(pa?"ਸਥਿਰ ਬਿਜਲੀ · ਬਿਨਾਂ ਤਾਰਾਂ ਦੇ ਆਕਰਸ਼ਣ":"STATIC ELECTRICITY · ATTRACTION WITHOUT WIRES")+'</text></svg>';
