 const hideAllClass9PhysicsControls=lab==="physics"&&cls===9&&exp>=1&&exp<=4;const specialNewton=!hideAllClass9PhysicsControls&&lab==="physics"&&cls===9&&exp===1&&it.kind==="newton";const hideGenericControls=false;const specialRefraction=!hideAllClass9PhysicsControls&&lab==="physics"&&((cls===9&&exp===3)||(cls===10&&exp===1))&&it.kind==="refraction";const specialPotential=!hideAllClass9PhysicsControls&&lab==="physics"&&cls===9&&exp===4&&it.kind==="potential";const quantitative=(lab==="electricity"&&cls===10)|| (lab==="physics"&&cls>=9&&["acceleration","newton","work","potential","reflection","refraction","lens","wave"].includes(it.kind)&&!(cls===10&&exp===0&&it.kind==="reflection")&&!(cls===10&&exp===1&&it.kind==="refraction"));const specialSeries=lab==="electricity"&&cls===9&&exp===2;const choiceOnly=(lab==="electricity"&&((cls===7&&(exp===0||exp===3))||(cls===8&&(exp===0||exp===1||exp===2))))||lab==="chemistry"||lab==="biology"||(lab==="physics"&&((cls===6&&exp>=1)||(cls===7&&exp<=4)||(cls===8&&exp<=4)||(cls===10&&exp===0&&it.kind==="reflection")||(cls===10&&exp===1&&it.kind==="refraction")));const hasSwitch=(lab==="electricity"&&["circuit","motor","electromagnet","magnetic_field","ohms","series_parallel","power","heating","cell"].includes(it.kind)&&!quantitative&&!specialSeries&&!choiceOnly);
 $("#app").innerHTML='<section class="lab-top"><button class="back-button" id="back">'+tr("back")+'</button><div class="lab-top-name"><span>'+ICON[lab]+'</span><div><strong>'+tr(lab)+'</strong><small>'+(lang==="pa"?"25 ਪ੍ਰਯੋਗ · ਜਮਾਤਾਂ 6–10":"25 experiments · Classes 6–10")+'</small></div></div></section><section class="lab-selectors"><label>'+tr("chooseClass")+'<select id="cl">'+[6,7,8,9,10].map(n=>'<option '+(cls===n?"selected":"")+' value="'+n+'">'+(lang==="pa"?n+"ਵੀਂ ਜਮਾਤ":"Class "+n)+'</option>').join("")+'</select></label><label>'+tr("chooseExperiment")+'<select id="ex">'+list().map((v,i)=>'<option value="'+i+'" '+(i===exp?"selected":"")+'>'+(i+1)+". "+esc(lang==="pa"?v.title_pa:v.title)+'</option>').join("")+'</select></label></section><section class="experiment-card"><div class="experiment-meta">'+(lang==="pa"?"ਜਮਾਤ "+cls+" · ਪ੍ਰਯੋਗ "+(exp+1)+" / 5":"CLASS "+cls+" · EXPERIMENT "+(exp+1)+" / 5")+'</div><h2>'+esc(name)+'</h2><p class="aim"><b>'+tr("aim")+':</b> '+esc(aim)+'</p><p class="helper">'+(lang==="pa"?"ਕੰਟਰੋਲ ਬਦਲੋ ਅਤੇ ਨਤੀਜੇ ਦਾ ਨਿਰੀਖਣ ਕਰੋ।":"Change a control and observe the result.")+'</p><div class="experiment-grid"><div class="control-panel '+(choiceOnly?"choice-only":"")+'"><h3>'+tr("controls")+'</h3>'+(hasSwitch?'<label>'+tr("switch")+'<select id="sw"><option value="1" '+(sw?"selected":"")+'>'+(lang==="pa"?"ਬੰਦ":"Closed")+'</option><option value="0" '+(!sw?"selected":"")+'>'+(lang==="pa"?"ਖੁੱਲ੍ਹਾ":"Open")+'</option></select></label>':'<label>'+((lab==="electricity"&&cls===10&&it.kind==="ohms")?(lang==="pa"?"ਵੋਲਟੇਜ (V)":"Voltage (V)"):cn[0])+' <output id="ao">'+a+'</output><input id="a" type="range" min="1" max="'+((lab==="electricity"&&cls===10&&it.kind==="ohms")?24:100)+'" value="'+a+'"></label><label>'+((lab==="electricity"&&cls===10&&it.kind==="ohms")?(lang==="pa"?"ਰੋਧ (Ω)":"Resistance (Ω)"):cn[1])+' <output id="bo">'+b+'</output><input id="b" type="range" min="1" max="'+((lab==="electricity"&&cls===10&&it.kind==="ohms")?12:100)+'" value="'+b+'"></label>')+(specialNewton||(os.length===3&&os[0]==="Observe the model"&&os[1]==="Compare the result"&&os[2]==="Explore the change")?"":'<label>'+(lang==="pa"?"ਸਥਿਤੀ ਚੁਣੋ":"Choose a situation")+'<select id="choice">'+os.map(o=>'<option value="'+esc(o)+'" '+(o===choice?"selected":"")+' >'+esc(displayChoice(o))+'</option>').join("")+'</select></label>')+(specialSeries?'<div class="switch-options"><label><input id="seriesMain" type="checkbox" '+(seriesMain?"checked":"")+'>'+(lang==="pa"?"ਲੜੀਵਾਰ ਸਰਕਟ ਦਾ ਮੁੱਖ ਸਵਿੱਚ":"Series main switch")+'</label><label><input id="parallelOne" type="checkbox" '+(parallelOne?"checked":"")+'>'+(lang==="pa"?"ਸਮਾਂਤਰ ਸ਼ਾਖਾ 1":"Parallel branch 1")+'</label><label><input id="parallelTwo" type="checkbox" '+(parallelTwo?"checked":"")+'>'+(lang==="pa"?"ਸਮਾਂਤਰ ਸ਼ਾਖਾ 2":"Parallel branch 2")+'</label></div>':'')+'</div><div class="visual-panel"><h3>'+tr("observation")+'</h3><div id="visual">'+visual(it)+'</div><p id="obs">'+esc(observe(it))+'</p></div></div><div class="conclusion"><b>'+tr("conclusion")+':</b> '+esc(note)+'</div>'+quiz(it)+'<div class="navigation"><button id="prev" class="back-button" '+(exp===0?"disabled":"")+'>'+tr("previous")+'</button><button id="next" class="primary-button">'+tr("next")+' →</button></div><p class="safety-note">'+tr("safe")+'</p></section>';
