  if(k==="osmosis")return svg('<path d="M125 55 V195 H275 V55" fill="#bfdbfe" fill-opacity=".35" stroke="#64748b" stroke-width="4"/><ellipse cx="200" cy="130" rx="45" ry="55" fill="#86efac" stroke="#15803d" stroke-width="4"/>'+[0,1,2,3,4].map(i=>'<path d="M'+(90+i*50)+' 90 v30 m0 0 l-7 -10 m7 10 l7 -10" stroke="#2563eb" stroke-width="3" fill="none"/>').join("")+'<text x="200" y="35" text-anchor="middle" fill="#28485b">WATER MOVEMENT</text>');
